    semio_framework_plugin::bounded_first_step_tool_proofs! {
        owner: EditorApp<PlaygroundEditor>,
        owner_file: "✏️s/🔌️plugins/🎪️demonstrator/🗿️artifacts/🎪️playground/🏅️standards/🔖️1/🪆️subsets/✳️any/✏️editor/🦀️.rs",
