    type Payload = ArtifactRetainedCommandPayload<EditorApp<VcsPlayApp>>;
    type Job = ArtifactRetainedCommandJob<EditorApp<VcsPlayApp>>;

    fn keys(&self) -> &[ToolFactoryKey] {
        &self.keys
    }

